```python
import os
import shutil

def delete_file(file_path):
    """Deletes a single file."""
    try:
        os.remove(file_path)
        print(f"File {file_path} deleted successfully.")
    except FileNotFoundError:
        print(f"File {file_path} not found.")
    except Exception as e:
        print(f"Error deleting file {file_path}: {e}")

def delete_directory(dir_path):
    """Deletes an entire directory and its contents."""
    try:
        shutil.rmtree(dir_path)
        print(f"Directory {dir_path} deleted successfully.")
    except FileNotFoundError:
        print(f"Directory {dir_path} not found.")
    except Exception as e:
        print(f"Error deleting directory {dir_path}: {e}")

def delete_files_in_directory(directory_path):
    """Deletes all files in a specified directory."""
    for file_name in os.listdir(directory_path):
        file_path = os.path.join(directory_path, file_name)
        if os.path.isfile(file_path):
            delete_file(file_path)

def delete_all_files_in_directory(directory_path):
    """Deletes all files and subdirectories in a specified directory."""
    for item in os.listdir(directory_path):
        item_path = os.path.join(directory_path, item)
        if os.path.isfile(item_path):
            delete_file(item_path)
        elif os.path.isdir(item_path):
            delete_directory(item_path)

if __name__ == "__main__":
    directory_path = input("Enter the directory path to delete files from: ")
    delete_all_files_in_directory(directory_path)
